<?php
require_once __DIR__.'/includes/functions.php'; must_login(); require_permission('scheduling'); check_csrf(); require_once __DIR__.'/config/database.php';
$days=[1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{$action=$_POST['action']??'';if($action==='save'){$esp=(int)($_POST['especialista_id']??0);$day=(int)($_POST['dia_semana']??0);$start=$_POST['hora_inicio']??'';$end=$_POST['hora_fin']??'';if(!$esp||!isset($days[$day])||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$start>=$end)throw new RuntimeException('Completa los datos y verifica que la hora final sea posterior a la inicial.');$q=$pdo->prepare('SELECT COUNT(*) FROM horarios_especialistas WHERE especialista_id=? AND dia_semana=? AND hora_inicio < ? AND hora_fin > ?');$q->execute([$esp,$day,$end,$start]);if($q->fetchColumn())throw new RuntimeException('Ese horario se cruza con otro horario registrado.');$q=$pdo->prepare('INSERT INTO horarios_especialistas(especialista_id,dia_semana,hora_inicio,hora_fin) VALUES(?,?,?,?)');$q->execute([$esp,$day,$start,$end]);flash('Horario registrado.');go('horarios.php');}if($action==='delete'){$pdo->prepare('DELETE FROM horarios_especialistas WHERE id=?')->execute([(int)$_POST['id']]);flash('Horario eliminado.');go('horarios.php');}}catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo guardar el horario.':$e->getMessage();}
$specs=$pdo->query("SELECT id,nombres,apellidos FROM especialistas WHERE estado='Activo' ORDER BY nombres")->fetchAll();$rows=$pdo->query('SELECT h.*,CONCAT(e.nombres," ",e.apellidos) especialista FROM horarios_especialistas h JOIN especialistas e ON e.id=h.especialista_id ORDER BY e.nombres,h.dia_semana,h.hora_inicio')->fetchAll();$title='Horarios de especialistas';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">CONFIGURACIÓN</span><h1>Horarios de especialistas</h1><p class="muted">Define los días y las horas en que cada especialista puede atender.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="split"><section class="panel form-panel"><h2>Agregar horario</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save"><label class="field"><span>Especialista</span><select name="especialista_id" required><option value="">Seleccionar</option><?php foreach($specs as $s):?><option value="<?=$s['id']?>"><?=e($s['nombres'].' '.$s['apellidos'])?></option><?php endforeach;?></select></label><label class="field"><span>Día</span><select name="dia_semana" required><?php foreach($days as $n=>$d):?><option value="<?=$n?>"><?=e($d)?></option><?php endforeach;?></select></label><label class="field"><span>Desde</span><input type="time" name="hora_inicio" required></label><label class="field"><span>Hasta</span><input type="time" name="hora_fin" required></label><button class="btn">Guardar horario</button></form></section><section class="panel table-panel"><h2>Horarios registrados</h2><div class="tablewrap"><table><thead><tr><th>Especialista</th><th>Día</th><th>Desde</th><th>Hasta</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['especialista'])?></td><td><?=e($days[(int)$r['dia_semana']]??'—')?></td><td><?=e(substr($r['hora_inicio'],0,5))?></td><td><?=e(substr($r['hora_fin'],0,5))?></td><td><form method="post" onsubmit="return confirm('¿Eliminar horario?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Eliminar</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">Aún no se registraron horarios.</td></tr><?php endif;?></tbody></table></div></section></div><?php require __DIR__.'/includes/footer.php';?>
